syntax = "proto3";
package pkg;

// Svc does things.
service Svc {
  // Get returns one thing.
  //   Indented detail stays indented.
  rpc Get(Req) returns (Resp) {
    option (openshell.options.v1.authorization) = {auth_mode: "bearer" scope: "s:read" workspace_role: "user"};
  }
  rpc Ping(stream Req) returns (google.protobuf.Empty);
  rpc Bare(Req) returns (Resp);
}

message Req {
  string name = 1;
}
message Resp {}
